css:
.bccmpc-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
    letter-spacing: 0.01em;
}

.bccmpc-sim-container h1,
.bccmpc-sim-container h3 {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
}

/* ---------- HEADER ---------- */
.bccmpc-sim-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    gap: 24px;
    padding: 24px 28px;
    margin-bottom: 24px;
    background: linear-gradient(90deg, rgba(0,191,255,0.08), rgba(0,255,136,0.04));
    border: 1px solid #1f2d3d;
    border-left: 4px solid #00bfff;
    border-radius: 8px;
}
.bccmpc-sim-header-left { flex: 1; min-width: 0; }
.bccmpc-sim-eyebrow {
    color: #00bfff;
    font-size: 0.7rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    margin-bottom: 8px;
    font-weight: 600;
}
.bccmpc-sim-header h1 {
    color: #ffffff;
    font-size: 1.5rem;
    font-weight: 700;
    margin: 0 0 6px 0;
    line-height: 1.25;
}
.bccmpc-sim-subtitle {
    color: #8a99b0;
    font-size: 0.85rem;
    letter-spacing: 0.04em;
}
.bccmpc-sim-meeting-pill {
    background: #0e1729;
    border: 1px solid #1f2d3d;
    border-radius: 999px;
    padding: 10px 18px;
    text-align: center;
    min-width: 140px;
}
.bccmpc-sim-meeting-label {
    display: block;
    color: #8a99b0;
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
}
.bccmpc-sim-meeting-counter {
    display: block;
    color: #00ff88;
    font-size: 1.25rem;
    font-weight: 700;
    letter-spacing: 0.05em;
    margin-top: 2px;
}

/* ---------- BRIEFING ---------- */
.bccmpc-sim-briefing {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00ff88;
    border-radius: 6px;
    padding: 22px 26px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.bccmpc-sim-briefing::after {
    content: '';
    position: absolute;
    top: 0; right: 0; bottom: 0;
    width: 200px;
    background: radial-gradient(circle at right, rgba(0,255,136,0.06), transparent 70%);
    pointer-events: none;
}
.bccmpc-sim-briefing-tag {
    color: #00ff88;
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 8px;
}
.bccmpc-sim-briefing-title {
    color: #ffffff;
    font-size: 1.2rem;
    font-weight: 700;
    margin-bottom: 10px;
}
.bccmpc-sim-briefing-text {
    color: #c5cfe0;
    font-size: 0.95rem;
    line-height: 1.55;
}

/* ---------- KPI GRID ---------- */
.bccmpc-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 14px;
    margin-bottom: 16px;
}
.bccmpc-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 18px 18px 16px 18px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.2s ease;
}
.bccmpc-sim-kpi-card:hover {
    border-color: #2d3f55;
    transform: translateY(-2px);
}
.bccmpc-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: #00bfff;
}
.bccmpc-sim-kpi-rate::before        { background: linear-gradient(90deg, #00ff88, #00bfff); }
.bccmpc-sim-kpi-inflation::before   { background: linear-gradient(90deg, #ff6b35, #ffb454); }
.bccmpc-sim-kpi-gdp::before         { background: linear-gradient(90deg, #00bfff, #6c8eff); }
.bccmpc-sim-kpi-unemployment::before{ background: linear-gradient(90deg, #c47bff, #6c8eff); }
.bccmpc-sim-kpi-gap::before         { background: linear-gradient(90deg, #ffb454, #ff6b35); }
.bccmpc-sim-kpi-credibility::before { background: linear-gradient(90deg, #00ff88, #c47bff); }

.bccmpc-sim-kpi-label {
    color: #8a99b0;
    font-size: 0.7rem;
    letter-spacing: 0.14em;
    text-transform: uppercase;
    margin-bottom: 8px;
    font-weight: 600;
}
.bccmpc-sim-kpi-value {
    font-size: 1.85rem;
    font-weight: 700;
    color: #ffffff;
    line-height: 1.1;
    margin-bottom: 6px;
}
.bccmpc-sim-kpi-rate .bccmpc-sim-kpi-value         { color: #00ff88; }
.bccmpc-sim-kpi-inflation .bccmpc-sim-kpi-value    { color: #ff6b35; }
.bccmpc-sim-kpi-gdp .bccmpc-sim-kpi-value          { color: #00bfff; }
.bccmpc-sim-kpi-unemployment .bccmpc-sim-kpi-value { color: #c47bff; }
.bccmpc-sim-kpi-gap .bccmpc-sim-kpi-value          { color: #ffb454; }
.bccmpc-sim-kpi-credibility .bccmpc-sim-kpi-value  { color: #00ff88; }

.bccmpc-sim-kpi-context {
    color: #8a99b0;
    font-size: 0.72rem;
    letter-spacing: 0.04em;
}

/* ---------- SECONDARY GRID ---------- */
.bccmpc-sim-secondary-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 12px;
    margin-bottom: 28px;
}
.bccmpc-sim-secondary-card {
    background: #0e1729;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    padding: 12px 16px;
    display: flex;
    flex-direction: column;
    gap: 4px;
}
.bccmpc-sim-secondary-label {
    color: #8a99b0;
    font-size: 0.65rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    font-weight: 600;
}
.bccmpc-sim-secondary-value {
    color: #e0e6f0;
    font-size: 1.1rem;
    font-weight: 600;
}

/* ---------- CONTROLS ---------- */
.bccmpc-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px 28px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.bccmpc-sim-controls::before {
    content: '';
    position: absolute;
    top: 0; left: 0; bottom: 0;
    width: 3px;
    background: linear-gradient(180deg, #00ff88, #00bfff);
}
.bccmpc-sim-controls-tag {
    color: #00bfff;
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 6px;
}
.bccmpc-sim-controls h3 {
    color: #ffffff;
    font-size: 1.1rem;
    font-weight: 700;
    margin: 0 0 18px 0;
}
.bccmpc-sim-control-grid {
    display: grid;
    grid-template-columns: 1fr 1.2fr;
    gap: 18px;
    margin-bottom: 18px;
}
.bccmpc-sim-control-row {
    display: flex;
    flex-direction: column;
    gap: 6px;
}
.bccmpc-sim-control-row label {
    color: #8a99b0;
    font-size: 0.78rem;
    letter-spacing: 0.05em;
    font-weight: 500;
}
.bccmpc-sim-controls input[type="number"],
.bccmpc-sim-controls input[type="text"],
.bccmpc-sim-controls select,
.bccmpc-sim-select {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 9px 12px;
    width: 100%;
    font-size: 0.9rem;
    font-family: inherit;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.bccmpc-sim-controls select:focus,
.bccmpc-sim-controls input:focus,
.bccmpc-sim-select:focus {
    outline: none;
    border-color: #00bfff;
    box-shadow: 0 0 0 2px rgba(0,191,255,0.2);
}
.bccmpc-sim-controls select option,
.bccmpc-sim-select option {
    background: #111827;
    color: #e0e6f0;
}
.bccmpc-sim-button-row {
    display: flex;
    gap: 12px;
    align-items: center;
    flex-wrap: wrap;
}
.bccmpc-sim-submit-btn {
    background: linear-gradient(90deg, #00ff88, #00bfff);
    border: none;
    color: #0a0f1e;
    font-weight: 700;
    letter-spacing: 0.04em;
    text-transform: uppercase;
    font-size: 0.85rem;
    padding: 11px 24px;
    border-radius: 4px;
    transition: transform 0.15s ease, box-shadow 0.2s ease;
}
.bccmpc-sim-submit-btn:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 18px rgba(0,255,136,0.25);
    color: #0a0f1e;
}
.bccmpc-sim-undo-btn {
    background: transparent;
    border: 1px solid #2d3f55;
    color: #8a99b0;
    border-radius: 4px;
    padding: 9px 18px;
    font-size: 0.8rem;
    letter-spacing: 0.04em;
}
.bccmpc-sim-undo-btn:hover {
    border-color: #00bfff;
    color: #00bfff;
    background: transparent;
}

/* ---------- REACTION PANEL ---------- */
.bccmpc-sim-reaction {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
    position: relative;
    overflow: hidden;
}
.bccmpc-sim-reaction::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #ff6b35, #ffb454, #00bfff);
}
.bccmpc-sim-reaction-tag {
    color: #ffb454;
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 14px;
}
.bccmpc-sim-reaction-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 16px;
    margin-bottom: 18px;
}
.bccmpc-sim-reaction-cell {
    background: #0e1729;
    border: 1px solid #1f2d3d;
    border-radius: 6px;
    padding: 14px 16px;
}
.bccmpc-sim-reaction-label {
    color: #8a99b0;
    font-size: 0.65rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    font-weight: 600;
    margin-bottom: 6px;
}
.bccmpc-sim-reaction-value {
    color: #ffffff;
    font-size: 1.05rem;
    font-weight: 600;
}
.bccmpc-sim-headline-block {
    background: rgba(255,180,84,0.06);
    border-left: 3px solid #ffb454;
    padding: 12px 16px;
    border-radius: 4px;
    margin-bottom: 14px;
}
.bccmpc-sim-headline-eyebrow {
    color: #ffb454;
    font-size: 0.65rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 6px;
}
.bccmpc-sim-headline-text {
    color: #f4ead2;
    font-size: 1rem;
    line-height: 1.45;
    font-style: italic;
}
.bccmpc-sim-coach {
    background: rgba(0,191,255,0.05);
    border-left: 3px solid #00bfff;
    padding: 12px 16px;
    border-radius: 4px;
}
.bccmpc-sim-coach-eyebrow {
    color: #00bfff;
    font-size: 0.65rem;
    letter-spacing: 0.16em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 6px;
}
.bccmpc-sim-coach-text {
    color: #cce8f7;
    font-size: 0.92rem;
    line-height: 1.55;
}

/* ---------- CHART ---------- */
.bccmpc-sim-chart-section {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.bccmpc-sim-chart-tag {
    color: #00bfff;
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 4px;
}
.bccmpc-sim-chart-section h3 {
    color: #ffffff;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 16px 0;
}
.bccmpc-sim-chart-wrapper {
    position: relative;
    height: 320px;
}

/* ---------- HISTORY ---------- */
.bccmpc-sim-history {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px 26px;
    margin-bottom: 24px;
}
.bccmpc-sim-history-tag {
    color: #00ff88;
    font-size: 0.65rem;
    letter-spacing: 0.18em;
    text-transform: uppercase;
    font-weight: 700;
    margin-bottom: 4px;
}
.bccmpc-sim-history h3 {
    color: #ffffff;
    font-size: 1.05rem;
    font-weight: 700;
    margin: 0 0 14px 0;
}
.bccmpc-sim-history-table {
    color: #e0e6f0;
    margin-bottom: 0;
}
.bccmpc-sim-history-table thead th {
    background: #0e1729;
    color: #00bfff;
    font-size: 0.7rem;
    letter-spacing: 0.12em;
    text-transform: uppercase;
    border: none;
    border-bottom: 1px solid #1f2d3d;
    padding: 10px 12px;
}
.bccmpc-sim-history-table tbody td {
    background: transparent;
    color: #c5cfe0;
    font-size: 0.85rem;
    padding: 10px 12px;
    border-top: 1px solid #1f2d3d;
}
.bccmpc-sim-history-table tbody tr:hover td {
    background: rgba(0,191,255,0.05);
}

/* ---------- RESPONSIVE ---------- */
@media (max-width: 768px) {
    .bccmpc-sim-container { padding: 18px; }
    .bccmpc-sim-header {
        flex-direction: column;
        align-items: stretch;
        padding: 18px 20px;
    }
    .bccmpc-sim-header h1 { font-size: 1.25rem; }
    .bccmpc-sim-meeting-pill { align-self: flex-start; }
    .bccmpc-sim-control-grid { grid-template-columns: 1fr; }
    .bccmpc-sim-kpi-grid { grid-template-columns: repeat(2, 1fr); }
    .bccmpc-sim-secondary-grid { grid-template-columns: repeat(2, 1fr); }
    .bccmpc-sim-kpi-value { font-size: 1.45rem; }
    .bccmpc-sim-chart-wrapper { height: 240px; }
}


/* --- EQIL 2026-08-07: focus, motion, completion panel --- */
.bccmpc-sim-select:focus-visible,
.bccmpc-sim-submit-btn:focus-visible,
.bccmpc-sim-undo-btn:focus-visible,
.bccmpc-sim-container :focus-visible {
    outline: 3px solid #00ff88;
    outline-offset: 2px;
    border-radius: 3px;
}
.bccmpc-sim-completion {
    background: #10182c;
    border: 1px solid #2d3f55;
    border-left: 5px solid #00ff88;
    border-radius: 6px;
    padding: 22px 26px;
    margin: 20px 0;
    color: #e6ecf5;
}
.bccmpc-sim-debrief h3 { margin: 0 0 10px; font-size: 1.1rem; color: #ffffff; }
.bccmpc-sim-debrief-headline { font-size: 1rem; margin-bottom: 14px; color: #e6ecf5; }
.bccmpc-sim-debrief-list {
    list-style: none; padding: 0; margin: 0 0 14px;
    display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 8px;
}
.bccmpc-sim-debrief-list li {
    display: flex; justify-content: space-between; gap: 12px;
    background: #0a0f1e; border: 1px solid #2d3f55; border-radius: 4px; padding: 8px 12px;
}
.bccmpc-sim-debrief-k { color: #8a99b0; font-size: 0.8rem; }
.bccmpc-sim-debrief-v { font-weight: 700; color: #ffffff; }
.bccmpc-sim-debrief-insights p { margin: 0 0 8px; font-size: 0.9rem; line-height: 1.5; color: #c3cddc; }
@media (prefers-reduced-motion: reduce) {
    .bccmpc-sim-container *,
    .bccmpc-sim-container *::before,
    .bccmpc-sim-container *::after {
        animation-duration: 0.01ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.01ms !important;
        scroll-behavior: auto !important;
    }
}

