            } else {
                commAdj = 0;
            }
            scoreImpact += commAdj;

            // Market reaction
            const bondYield = Math.round((newRate + 0.55 + (surprise * 0.45)) * 100) / 100;
            const fxMove = Math.round(surprise * 2.6 * 10) / 10;
            const equityMove = Math.round((-absSurprise * 4.5 + (surprise > 0.5 ? -1.5 : 0)) * 10) / 10;

            // Effective inflation outcome reported (next-period view)
            const effectiveInflation = this._computeEffectiveInflation(round, d.rateChange);

            // Assessment text key
            let assessmentKey = 'assess_misjudged';
            if (scoreImpact >= 14)      assessmentKey = 'assess_oncurve';
            else if (scoreImpact >= 6)  assessmentKey = 'assess_acceptable';
            else if (scoreImpact >= -3) assessmentKey = 'assess_borderline';
            else if (scoreImpact >= -10) assessmentKey = 'assess_misjudged';
            else                         assessmentKey = 'assess_shock';

            const headline = this._generateHeadline(round, d, scoreImpact);
            const coach = this._generateCoachNote(round, d);

            // Mutate domainState
            state.domainState.currentRate = newRate;
            state.domainState.credibility = Math.max(0, Math.min(150, state.domainState.credibility + scoreImpact));
            state.domainState.totalScore = state.domainState.totalScore + scoreImpact;

            state.domainState.rateHistory.push(newRate);
            state.domainState.inflationHistory.push(effectiveInflation);
            state.domainState.targetTopHistory.push(3.0);
            state.domainState.targetBottomHistory.push(1.0);
            state.domainState.credibilityHistory.push(state.domainState.credibility);

            // Platform score 0 to 100: same linear map as getPerformanceSummary, cumulative scoreImpact over the band minus 18 to plus 17 per meeting played so far
            const playedSoFar = Math.max(1, state.domainState.rateHistory.length);
            const bandLow = -18 * playedSoFar;
            const bandHigh = 17 * playedSoFar;
            const runningScore = Math.max(0, Math.min(100, Math.round(((state.domainState.totalScore - bandLow) / (bandHigh - bandLow)) * 100)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: runningScore });

            // Set up next round display
            const nextIdx = state.currentPeriod;
            if (nextIdx < this.ROUNDS.length) {
                const nextRound = this.ROUNDS[nextIdx];
                state.domainState.displayInflation = nextRound.indicators.inflation;
                state.domainState.displayCoreInflation = nextRound.indicators.coreInflation;
                state.domainState.displayGdp = nextRound.indicators.gdp;
                state.domainState.displayUnemployment = nextRound.indicators.unemployment;
                state.domainState.displayOutputGap = nextRound.indicators.outputGap;
                state.domainState.displayWage = nextRound.indicators.wage;
                state.domainState.displayCredit = nextRound.indicators.credit;
            }

            // Show reaction panel
            const panel = document.getElementById('reactionPanel');
            if (panel) panel.style.display = 'block';

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: period + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                meetingLabel: this._meetingLabel(idx),
                rateChange: d.rateChange,
                rateChangeBps: Math.round(d.rateChange * 100),
                newRate: newRate,
                guidance: d.guidance,
                guidanceLabel: this._guidanceLabel(d.guidance),
                bondYield: bondYield,
                fxMove: fxMove,
                equityMove: equityMove,
                scoreImpact: scoreImpact,
                assessment: window.mySimulation.t(assessmentKey),
                headline: headline,
                coachNote: coach,
                inflation: round.indicators.inflation,
                coreInflation: round.indicators.coreInflation,
                gdp: round.indicators.gdp,
                unemployment: round.indicators.unemployment,
                outputGap: round.indicators.outputGap,
                effectiveInflation: effectiveInflation,
                credibility: state.domainState.credibility
            };
        }

        _computeEffectiveInflation(round, rateChange) {
            // Stylised: the inflation print attached to this round (post-decision residual)
            // adjusts modestly based on whether the move was calibrated.
            const dev = rateChange - round.optimalRate;
            let infl = round.indicators.inflation;
            if (round.scenario === 'boom') {
                if (dev <= -0.25) infl += 0.4;
                else if (dev >= 0.5) infl += 0.2;
                else infl -= 0.05;
            } else if (round.scenario === 'lag') {
                if (dev >= 0.25) infl += 0.1;
                else infl -= 0.05;
            } else if (round.scenario === 'shock') {
                if (dev > 0) infl += 0.05;
                else if (dev < 0) infl += 0.3;
            } else if (round.scenario === 'exit') {
                if (dev <= -0.5) infl += 0.4;
                else infl -= 0.05;
            }
            return Math.round(infl * 10) / 10;
        }

        _meetingLabel(idx) {
            if (idx >= 0 && idx < this.ROUNDS.length) return this._t('meeting_short_' + (idx + 1));
            return 'M' + (idx + 1);
