            const map = {
                'dovish': window.mySimulation.t('guidance_dovish'),
                'neutral': window.mySimulation.t('guidance_neutral'),
                'data-dependent': window.mySimulation.t('guidance_datadep'),
                'lookthrough': window.mySimulation.t('guidance_lookthrough'),
                'hawkish': window.mySimulation.t('guidance_hawkish')
            };
            return map[g] || g;
        }

        _generateHeadline(round, d, scoreImpact) {
            const bps = Math.round(d.rateChange * 100);
            const sign = bps > 0 ? '+' : '';
            // Round 1 - boom
            if (round.scenario === 'boom') {
                if (d.rateChange === 0) return window.mySimulation.t('hl_boom_hold');
                if (d.rateChange < 0) return window.mySimulation.t('hl_boom_cut');
                if (d.rateChange === 0.25) return window.mySimulation.t('hl_boom_25');
                if (d.rateChange === 0.50) return window.mySimulation.t('hl_boom_50');
                if (d.rateChange === 0.75) return window.mySimulation.t('hl_boom_75');
                return window.mySimulation.t('hl_boom_100');
            }
            // Round 2 - lag
            if (round.scenario === 'lag') {
                if (d.rateChange === 0) return window.mySimulation.t('hl_lag_hold');
                if (d.rateChange < 0) return window.mySimulation.t('hl_lag_cut');
                if (d.rateChange <= 0.25) return window.mySimulation.t('hl_lag_25');
                return window.mySimulation.t('hl_lag_high');
            }
            // Round 3 - shock
            if (round.scenario === 'shock') {
                if (d.rateChange === 0 && d.guidance === 'lookthrough') return window.mySimulation.t('hl_shock_lookthrough');
                if (d.rateChange === 0) return window.mySimulation.t('hl_shock_hold');
                if (d.rateChange < 0) return window.mySimulation.t('hl_shock_cut');
                if (d.rateChange <= 0.50) return window.mySimulation.t('hl_shock_modesthike');
                return window.mySimulation.t('hl_shock_aggressive');
            }
            // Round 4 - exit
            if (d.rateChange === 0) return window.mySimulation.t('hl_exit_hold');
            if (d.rateChange === -0.25) return window.mySimulation.t('hl_exit_25cut');
            if (d.rateChange <= -0.50) return window.mySimulation.t('hl_exit_deepcut');
            return window.mySimulation.t('hl_exit_hike');
        }

        _generateCoachNote(round, d) {
            const dev = d.rateChange - round.optimalRate;
            if (round.scenario === 'boom') {
                if (d.rateChange === 0) return window.mySimulation.t('coach_boom_hold');
                if (d.rateChange === 0.50) return window.mySimulation.t('coach_boom_50');
                if (d.rateChange >= 1.0) return window.mySimulation.t('coach_boom_panic');
                if (d.rateChange === 0.25) return window.mySimulation.t('coach_boom_25');
                if (d.rateChange < 0) return window.mySimulation.t('coach_boom_cut');
                return window.mySimulation.t('coach_boom_other');
            }
            if (round.scenario === 'lag') {
                if (d.rateChange === 0) return window.mySimulation.t('coach_lag_hold');
                if (d.rateChange > 0) return window.mySimulation.t('coach_lag_overhike');
                return window.mySimulation.t('coach_lag_cut');
            }
            if (round.scenario === 'shock') {
                if (d.rateChange === 0 && d.guidance === 'lookthrough') return window.mySimulation.t('coach_shock_perfect');
                if (d.rateChange === 0) return window.mySimulation.t('coach_shock_hold_nocomms');
                if (d.rateChange > 0) return window.mySimulation.t('coach_shock_hike');
                return window.mySimulation.t('coach_shock_cut');
            }
            if (d.rateChange === -0.25) return window.mySimulation.t('coach_exit_25');
            if (d.rateChange === 0) return window.mySimulation.t('coach_exit_hold');
            if (d.rateChange <= -0.50) return window.mySimulation.t('coach_exit_deep');
            return window.mySimulation.t('coach_exit_hike');
        }

