        getPerformanceSummary(history) {
            if (!history.length) return {};
            const totalCred = history.reduce((s, r) => s + (r.results && r.results.scoreImpact ? r.results.scoreImpact : 0), 0);
            const finalCred = history[history.length - 1].results && history[history.length - 1].results.credibility !== undefined
                ? history[history.length - 1].results.credibility
                : 100;
            const finalRate = history[history.length - 1].results && history[history.length - 1].results.newRate !== undefined
                ? history[history.length - 1].results.newRate
                : 3.50;
            const finalInflation = history[history.length - 1].results && history[history.length - 1].results.effectiveInflation !== undefined
                ? history[history.length - 1].results.effectiveInflation
                : 0;

            let performance = 'developing';
            if (totalCred >= 30 && finalCred >= 110) performance = 'central_banker';
            else if (totalCred >= 15 && finalCred >= 100) performance = 'credible';
            else if (totalCred >= 0) performance = 'acceptable';
            else if (totalCred >= -20) performance = 'shaky';
            else performance = 'lost_market';
            const perfKey = 'perf_' + performance;

            // 0-100 composite for the gradebook. Per-meeting scoreImpact runs from
            // -18 to +17, so the theoretical band over N meetings is [-18N, +17N];
            // this maps that band linearly onto 0-100 and clamps. The underlying
            // credibility model, deltas and thresholds are unchanged.
            const meetings = history.length || 1;
            const worst = -18 * meetings;
            const best = 17 * meetings;
            const overall = Math.max(0, Math.min(100,
                Math.round(((totalCred - worst) / (best - worst)) * 100)));

            const insights = [];
            if (totalCred >= 30) insights.push(window.mySimulation.t('insight_excellent'));
            if (finalInflation > 3.5) insights.push(window.mySimulation.t('insight_high_infl'));
            if (finalInflation < 1.0 && finalInflation > 0) insights.push(window.mySimulation.t('insight_under_target'));
            if (finalRate > 5.0) insights.push(window.mySimulation.t('insight_overtight'));
            if (finalRate < 2.5 && finalInflation > 3.0) insights.push(window.mySimulation.t('insight_too_loose'));
            if (insights.length === 0) insights.push(window.mySimulation.t('insight_default'));

            return {
                composite: overall,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                totalCredibilityDelta: totalCred,
                finalCredibility: finalCred,
                finalRate: finalRate,
                finalInflation: finalInflation,
                meetings: meetings,
                performance: performance,
                performanceKey: perfKey,
                performanceLabel: this._t(perfKey),
                insights: insights
            };
        }

