            };
            const num = function(v, dp) { return (typeof v === 'number') ? v.toFixed(dp) : '-'; };
            const rows = [
                [t('debrief_cred'), (s.totalCredibilityDelta >= 0 ? '+' : '') + esc(s.totalCredibilityDelta)],
                [t('debrief_final_cred'), esc(Math.round(s.finalCredibility || 0))],
                [t('debrief_final_rate'), num(s.finalRate, 2) + '%'],
                [t('debrief_final_infl'), num(s.finalInflation, 1) + '%']
            ].map(function(r) {
                return '<li><span class="bccmpc-sim-debrief-k">' + esc(r[0]) + '</span>' +
                       '<span class="bccmpc-sim-debrief-v">' + r[1] + '</span></li>';
            }).join('');
            const ins = (s.insights || []).map(function(x) { return '<p>' + esc(x) + '</p>'; }).join('');
            return '<div class="bccmpc-sim-debrief">' +
                     '<h3>' + esc(t('debrief_heading')) + '</h3>' +
                     '<p class="bccmpc-sim-debrief-headline">' + esc(t('debrief_score')) + ' <strong>' +
                       esc(s.overallScore || 0) + '/100</strong> &middot; ' + esc(s.performanceLabel || '') + '</p>' +
                     '<ul class="bccmpc-sim-debrief-list">' + rows + '</ul>' +
